import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { NavMain } from "@/blocks/sidebar-06/components/sidebar-06-nav-main";
import { SidebarOptInForm } from "@/blocks/sidebar-06/components/sidebar-06-opt-in-form";
import { SidebarBrand } from "@/blocks/sidebar-shared/sidebar-brand";
import { docsNav } from "@/blocks/sidebar-shared/sidebar-data";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarRail } from "@/components/ui/sidebar";
export const AppSidebar = defineUi<UI.ComponentProps<typeof Sidebar>>("AppSidebar", [], (_props, {
  slots: _slots
}) => {
  const props = computed(() => omitProps(_props, []));
  return () => {
    return <Sidebar role="navigation" aria-label="Field guide" {...domProps(props.value)}>
      <SidebarHeader>
        <SidebarBrand title="Field guide" subtitle="v1.0.0" icon="book-open" />
      </SidebarHeader>
      <SidebarContent>
        <NavMain items={docsNav} />
      </SidebarContent>
      <SidebarFooter>
        <div class="p-1 [@media(max-height:34rem)]:hidden">
          <SidebarOptInForm />
        </div>
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import type { NavSection } from "@/blocks/sidebar-shared/sidebar-data";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";
export const NavMain = defineUi<{
  items: NavSection[];
}>("NavMain", ["items"], (_props, {
  slots: _slots
}) => {
  const items = computed(() => _props["items"]);
  const _hook1 = useSidebar();
  const isMobile = computed(() => _hook1.value.isMobile);
  return () => {
    return <SidebarGroup>
      <SidebarMenu>
        {items.value.map(section => {
          const holdsCurrent = section.items.some(item => item.isActive);
          return <SidebarMenuItem key={section.title}>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <SidebarMenuButton isActive={holdsCurrent} aria-current={holdsCurrent ? "true" as const : undefined} class="data-[state=open]:ll-swipe">
                    {section.title}
                    <Icon name="ellipsis" class="ms-auto" />
                  </SidebarMenuButton>
                </DropdownMenuTrigger>
                {section.items.length ? <DropdownMenuContent side={isMobile.value ? "bottom" as const : "right" as const} align={isMobile.value ? "end" as const : "start" as const} class="min-w-56">
                    {section.items.map(item => <DropdownMenuItem asChild key={item.title}>
                        <a href={item.url} aria-current={item.isActive ? "page" as const : undefined} class={item.isActive ? "font-bold" as const : undefined}>
                          {item.title}
                          {item.isActive ? <Icon name="check" class="ms-auto" /> : null}
                        </a>
                      </DropdownMenuItem>)}
                  </DropdownMenuContent> : null}
              </DropdownMenu>
            </SidebarMenuItem>;
        })}
      </SidebarMenu>
    </SidebarGroup>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, useId, shallowRef } from "vue";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { SidebarInput } from "@/components/ui/sidebar";
export const SidebarOptInForm = defineUi<{
  onSubmit?: (email: string) => void;
}>("SidebarOptInForm", ["onSubmit"], (_props, {
  slots: _slots
}) => {
  const onSubmit = computed(() => _props["onSubmit"]);
  const id = useId();
  const sent = shallowRef(initialState(false));
  const setSent = stateSetter(sent);
  const error = shallowRef<string | null>(initialState(null));
  const setError = stateSetter(error);
  return () => {
    return <Card class="gap-2 py-4">
      <CardHeader class="px-4">
        <CardTitle class="text-xl">Get the postcard</CardTitle>
        <CardDescription>A short note on new pens and papers, every other Friday. Only ink, no spam.</CardDescription>
      </CardHeader>
      <CardContent class="px-4">
        {sent.value ? <p role="status" class="font-hand text-sm text-green">
            Thank you! Watch your mailbox on Friday.
          </p> : <form class="grid gap-2.5" novalidate onSubmit={(event: SubmitEvent) => {
          event.preventDefault();
          const value = new FormData(event.currentTarget as HTMLFormElement).get("email");
          const email = typeof value === "string" ? value.trim() : "" as const;
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            setError("That does not look like an email address yet.");
            return;
          }
          setError(null);
          onSubmit.value?.(email);
          setSent(true);
        }}>
            <Label for={id} class="sr-only">
              Email address
            </Label>
            <SidebarInput id={id} name="email" type="email" autoComplete="email" required placeholder="you@example.com" aria-invalid={error.value ? true : undefined} aria-describedby={error.value ? `${id}-error` : undefined} onChange={() => error.value && setError(null)} />
            {error.value ? <p id={`${id}-error`} role="alert" class="font-hand text-sm text-red">
                {error.value}
              </p> : null}
            <Button size="sm" class="w-full" type="submit">
              Subscribe
            </Button>
          </form>}
      </CardContent>
    </Card>;
  };
});

